# background color is the non-zero color in demos (7, 8), i.e. most common. Only recolor multi-cell comps that are NOT background-colored; leave marker singles untouched; don't touch background cells.
def f(g):
    from collections import Counter
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and g[x][y]==col and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                comps.append(comp)
    bs=sorted([b for b in comps if len(b)>1],key=lambda b:(min(a for a,_ in b),min(c for _,c in b)))
    mr=sorted([(g[m[0][0]][m[0][1]],m[0]) for m in comps if len(m)==1], key=lambda p:p[1])
    out=[row[:] for row in g]
    for b,m in zip(bs,mr):
        for a,c in b: out[a][c]=m[0]
    return out
